<script>
import mpx, { createPage } from '@mpxjs/core'
import { fetchTrendingKeywords, requestSuggestions } from '../../services/search'

createPage({
  data: {
    keyword: '',
    trendingKeywords: [],
    suggestions: [],
    requestTask: null,
    suggestionRequestId: 0
  },
  async onLoad () {
    this.trendingKeywords = await fetchTrendingKeywords()
  },
  onUnload () {
    this.cancelSuggestionRequest()
  },
  methods: {
    onKeywordInput (event) {
      this.search(event.detail.value.trim())
    },
    chooseKeyword (keyword) {
      this.search(keyword)
    },
    cancelSuggestionRequest () {
      this.suggestionRequestId += 1
      if (this.requestTask) {
        this.requestTask.abort()
        this.requestTask = null
      }
    },
    search (keyword) {
      this.keyword = keyword
      this.cancelSuggestionRequest()

      if (!keyword) {
        this.suggestions = []
        return
      }

      const requestId = this.suggestionRequestId
      const requestPromise = requestSuggestions(keyword)
      this.requestTask = requestPromise.__returned

      requestPromise.then(({ data }) => {
        if (this.suggestionRequestId !== requestId || this.keyword !== keyword) return
        this.suggestions = data.list
      }).catch(() => {
        if (this.suggestionRequestId !== requestId || this.keyword !== keyword) return
        mpx.showToast({
          title: '搜索失败',
          icon: 'none'
        })
      }).finally(() => {
        if (this.suggestionRequestId === requestId) {
          this.requestTask = null
        }
      })
    },
    openProduct (productId) {
      mpx.navigateTo({
        url: `/pages/product/detail?id=${productId}`
      })
    }
  }
})
</script>

<style scoped>
.search-page { padding: 24rpx; }
.trending, .suggestions { margin-top: 24rpx; }
</style>
import mpx from '@mpxjs/core'

export function fetchTrendingKeywords () {
  return mpx.request({
    url: '/api/search/trending'
  }).then(({ data }) => data)
}

export function requestSuggestions (keyword) {
  return mpx.request({
    url: '/api/search/suggest',
    data: { keyword }
  })
}
